-- public.crate_open_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.crate_open_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare v_at record; v_c creature; v_cur creature; v_d species_def; v_dd deed;
begin
  select * into v_at from crate_aimed(p_world, p_uid, p_target);
  if v_at.v_item is null and v_at.v_placed is null then return 'Not a wildermon crate.'; end if;
  if v_at.v_creature is null then return 'Crate empty.'; end if;
  select * into v_c from creature where world_id = p_world and id = v_at.v_creature;
  if not found then return 'Crate empty.'; end if;
  if v_c.mode <> 'stored' then return v_c.name || ' is not in it.'; end if;
  if v_c.keeper is distinct from p_uid then return v_c.name || ': not yours.'; end if;
  if v_at.v_item is not null and exists (select 1 from item i where i.world_id = p_world and i.id = v_at.v_item and i.deal is not null) then
    return 'Crate offered in a deal: take the offer back first.';
  end if;
  if v_at.v_placed is not null and not placed_in_reach(p_world, p_uid, v_at.v_placed) then
    return 'Stand next to the crate.';
  end if;
  if p_action = 'crate_follow' then
    select * into v_cur from creature where world_id = p_world and keeper = p_uid and mode = 'active' and hitched_to is null limit 1;
    if v_cur.id is not null and v_cur.rider is not null then
      return 'Get down off ' || v_cur.name || ' first.';
    end if;
    if v_cur.id is not null then return pannier_exit_refusal(p_world, v_cur); end if;
    return null;
  end if;
  v_dd := my_deed(p_world, p_uid);
  if v_dd.world_id is null then return 'No settlement.'; end if;
  select * into v_d from species_def where id = v_c.species;
  if v_d.gathers is null and v_d.style is distinct from 'spar' then return v_d.name || ': no task.'; end if;
  if v_d.gathers is not null and not worker_job_ported(v_d.gathers) then
    return 'Not on islands yet: '
      || (select verb from gather_def where id = v_d.gathers) || '.';
  end if;
  if workers_on_deed(p_world, p_uid) >= worker_cap(p_world, p_uid) then
    return v_dd.name || ' full: ' || worker_cap(p_world, p_uid) || ' workers at level '
      || v_dd.level || '.';
  end if;
  return null;
end $function$
